{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"io"
	"os"
)

var (
	encryptFlag   bool
	decryptFlag   bool
	outputFlag    string
	armorFlag     bool
	passphraseFlag bool
	recipientFlag []string
	recipientsFileFlag []string
	identityFlag  []string
)

func main() {
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage:\n")
		fmt.Fprintf(os.Stderr, "    age [--encrypt] (-r RECIPIENT | -R PATH)... [--armor] [-o OUTPUT] [INPUT]\n")
		fmt.Fprintf(os.Stderr, "    age [--encrypt] --passphrase [--armor] [-o OUTPUT] [INPUT]\n")
		fmt.Fprintf(os.Stderr, "    age --decrypt [-i PATH]... [-o OUTPUT] [INPUT]\n")
		fmt.Fprintf(os.Stderr, "\nOptions:\n")
		fmt.Fprintf(os.Stderr, "    -e, --encrypt               Encrypt the input to the output. Default if omitted.\n")
		fmt.Fprintf(os.Stderr, "    -d, --decrypt               Decrypt the input to the output.\n")
		fmt.Fprintf(os.Stderr, "    -o, --output OUTPUT         Write the result to the file at path OUTPUT.\n")
		fmt.Fprintf(os.Stderr, "    -a, --armor                 Encrypt to a PEM encoded format.\n")
		fmt.Fprintf(os.Stderr, "    -p, --passphrase            Encrypt with a passphrase.\n")
		fmt.Fprintf(os.Stderr, "    -r, --recipient RECIPIENT   Encrypt to the specified RECIPIENT. Can be repeated.\n")
		fmt.Fprintf(os.Stderr, "    -R, --recipients-file PATH  Encrypt to recipients listed at PATH. Can be repeated.\n")
		fmt.Fprintf(os.Stderr, "    -i, --identity PATH         Use the identity file at PATH. Can be repeated.\n")
		fmt.Fprintf(os.Stderr, "\nINPUT defaults to standard input, and OUTPUT defaults to standard output.\n")
		fmt.Fprintf(os.Stderr, "If OUTPUT exists, it will be overwritten.\n")
		fmt.Fprintf(os.Stderr, "\nRECIPIENT can be an age public key generated by age-keygen (\"age1...\")\n")
		fmt.Fprintf(os.Stderr, "or an SSH public key (\"ssh-ed25519 AAAA...\", \"ssh-rsa AAAA...\").\n")
		fmt.Fprintf(os.Stderr, "\nRecipient files contain one or more recipients, one per line. Empty lines\n")
		fmt.Fprintf(os.Stderr, "and lines starting with \"#\" are ignored as comments. \"-\" may be used to\n")
		fmt.Fprintf(os.Stderr, "read recipients from standard input.\n")
		fmt.Fprintf(os.Stderr, "\nIdentity files contain one or more secret keys (\"AGE-SECRET-KEY-1...\"),\n")
		fmt.Fprintf(os.Stderr, "one per line, or an SSH key. Empty lines and lines starting with \"#\" are\n")
		fmt.Fprintf(os.Stderr, "ignored as comments. Passphrase encrypted age files can be used as\n")
		fmt.Fprintf(os.Stderr, "identity files. Multiple key files can be provided, and any unused ones\n")
		fmt.Fprintf(os.Stderr, "will be ignored. \"-\" may be used to read identities from standard input.\n")
		fmt.Fprintf(os.Stderr, "\nWhen --encrypt is specified explicitly, -i can also be used to encrypt to an\n")
		fmt.Fprintf(os.Stderr, "identity file symmetrically, instead or in addition to normal recipients.\n")
		fmt.Fprintf(os.Stderr, "\nExample:\n")
		fmt.Fprintf(os.Stderr, "    $ age-keygen -o key.txt\n")
		fmt.Fprintf(os.Stderr, "    Public key: age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p\n")
		fmt.Fprintf(os.Stderr, "    $ tar cvz ~/data | age -r age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p > data.tar.gz.age\n")
		fmt.Fprintf(os.Stderr, "    $ age --decrypt -i key.txt -o data.tar.gz data.tar.gz.age\n")
	}

	flag.BoolVar(&encryptFlag, "e", false, "")
	flag.BoolVar(&encryptFlag, "encrypt", false, "")
	flag.BoolVar(&decryptFlag, "d", false, "")
	flag.BoolVar(&decryptFlag, "decrypt", false, "")
	flag.StringVar(&outputFlag, "o", "", "")
	flag.StringVar(&outputFlag, "output", "", "")
	flag.BoolVar(&armorFlag, "a", false, "")
	flag.BoolVar(&armorFlag, "armor", false, "")
	flag.BoolVar(&passphraseFlag, "p", false, "")
	flag.BoolVar(&passphraseFlag, "passphrase", false, "")

	flag.Func("r", "", func(s string) error {
		recipientFlag = append(recipientFlag, s)
		return nil
	})
	flag.Func("recipient", "", func(s string) error {
		recipientFlag = append(recipientFlag, s)
		return nil
	})
	flag.Func("R", "", func(s string) error {
		recipientsFileFlag = append(recipientsFileFlag, s)
		return nil
	})
	flag.Func("recipients-file", "", func(s string) error {
		recipientsFileFlag = append(recipientsFileFlag, s)
		return nil
	})
	flag.Func("i", "", func(s string) error {
		identityFlag = append(identityFlag, s)
		return nil
	})
	flag.Func("identity", "", func(s string) error {
		identityFlag = append(identityFlag, s)
		return nil
	})

	versionFlag := flag.Bool("version", false, "")

	flag.Parse()

	if *versionFlag {
		fmt.Println("v0.0.0-20260414014000-96fce988442d")
		return
	}

	if decryptFlag && (encryptFlag || armorFlag || passphraseFlag || len(recipientFlag) > 0 || len(recipientsFileFlag) > 0) {
		// This is not exactly how age behaves but close enough for now
	}

    // Default mode is encrypt if -d is not specified
    if !decryptFlag {
        encryptFlag = true
    }

    if decryptFlag {
        runDecrypt()
    } else {
        runEncrypt()
    }
}

func runEncrypt() {
    // Check for recipients
    if len(recipientFlag) == 0 && len(recipientsFileFlag) == 0 && !passphraseFlag && len(identityFlag) == 0 {
        fmt.Fprintf(os.Stderr, "age: error: missing recipients\n")
        fmt.Fprintf(os.Stderr, "age: hint: did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?\n")
        fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
        os.Exit(1)
    }
    // TODO: implement encryption
}

func runDecrypt() {
    // TODO: implement decryption
}
EOF
go build -o age main.go
./age
"}

