var gen = []int{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
func polmod(values []int) int {
	chk := 1
	for _, v := range values {
		b := chk >> 25
		chk = (chk&0x1ffffff)<<5 ^ v
		for i := 0; i < 5; i++ {
			if (b>>i)&1 == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}
func hrpExpand(hrp string) []int {
	res := make([]int, len(hrp)*2+1)
	for i, c := range hrp {
		res[i] = int(c >> 5)
		res[i+len(hrp)+1] = int(c & 31)
	}
	res[len(hrp)] = 0
	return res
}
func createChecksum(hrp string, data []int) []int {
	values := append(hrpExpand(hrp), data...)
	values = append(values, []int{0, 0, 0, 0, 0, 0}...)
	mod := polmod(values) ^ 1
	res := make([]int, 6)
	for i := 0; i < 6; i++ {
		res[i] = (mod >> (5 * (5 - i))) & 31
	}
	return res
}
func verifyChecksum(hrp string, data []int) bool {
	return polmod(append(hrpExpand(hrp), data...)) == 1
}
func encodeBech32(hrp string, data []int) string {
	combined := append(data, createChecksum(hrp, data)...)
	var sb strings.Builder
	sb.WriteString(hrp)
	sb.WriteByte('1')
	for _, v := range combined {
		sb.WriteByte(charset[v])
	}
	return sb.String()
}
func decodeBech32(bech string) (string, []int, error) {
	if len(bech) < 8 {
		return "", nil, fmt.Errorf("too short")
	}
	bech = strings.ToLower(bech)
	pos := strings.LastIndex(bech, "1")
	if pos < 1 || pos+7 > len(bech) {
		return "", nil, fmt.Errorf("invalid separator")
	}
	hrp := bech[:pos]
	data := make([]int, len(bech)-pos-1)
	for i := 0; i < len(data); i++ {
		idx := strings.IndexByte(charset, bech[pos+1+i])
		if idx == -1 {
			return "", nil, fmt.Errorf("invalid character")
		}
		data[i] = idx
	}
	if !verifyChecksum(hrp, data) {
		return "", nil, fmt.Errorf("invalid checksum")
	}
	return hrp, data[:len(data)-6], nil
