func convertBits(data []int, from, to int, pad bool) ([]int, error) {
	acc := 0
	bits := 0
	var res []int
	maxv := (1 << to) - 1
	for _, v := range data {
		acc = (acc << from) | v
		bits += from
		for bits >= to {
			bits -= to
			res = append(res, (acc>>bits)&maxv)
		}
	}
	if pad {
		if bits > 0 {
			res = append(res, (acc<<(to-bits))&maxv)
		}
	}
